      dns_how_title: 'Cómo funcionan las búsquedas DNS',
      dns_how_text: 'DNS (Domain Name System) es la agenda de internet. Cuando escribes example.com en un navegador, DNS traduce ese nombre legible por humanos a la dirección IP que la computadora realmente necesita para conectarse. Esta página consulta todos los tipos de registro comunes — A, AAAA, MX, TXT, NS, CNAME, SOA — en paralelo y agrupa las respuestas. Las consultas se envían por DNS-over-HTTPS (Google + Cloudflare) para que tus búsquedas sean privadas.',
