      downdetector_hero_subtitle: 'Estado operativo en vivo + historial de incidentes de 24 horas para más de 50 servicios populares. Busca cualquier servicio: los conocidos se abren aquí, los desconocidos enlazan a Downdetector.',
      downdetector_search_label: 'Nombre de servicio o URL',
