      // DNS page (now defaults to All records)
      dns_how_title: 'Comment fonctionnent les recherches DNS',
      dns_how_text: 'DNS (Domain Name System) est l’annuaire d’Internet. Quand vous tapez example.com dans un navigateur, le DNS traduit ce nom lisible par l’homme en l’adresse IP dont l’ordinateur a besoin pour se connecter. Cette page interroge tous les types d’enregistrements courants — A, AAAA, MX, TXT, NS, CNAME, SOA — en parallèle et regroupe les réponses. Les requêtes passent par DNS-over-HTTPS (Google + Cloudflare) pour rester privées.',
