      front_hero_subtitle: 'Drei saubere Tools, um deine IP zu prüfen, deine Verbindungs­geschwindigkeit zu testen und DNS-Einträge nachzuschlagen — alles im Browser, ohne Konto.',
      front_feature_eyebrow: 'Tool auswählen',
