      front_feature_status_title: 'Service-Status',
      front_feature_status_desc: 'Ist es für alle down oder nur für dich? Prüfe den Live-Status von Cloudflare, GitHub, Discord, OpenAI, Vercel und 11 weiteren. Daten direkt von deren offiziellen Statusseiten.',
      front_cta: 'Öffnen',
      front_how_title: 'So funktioniert es',
      front_how_text: 'Jede Prüfung läuft direkt in deinem Browser — wir speichern keine Logs, wir analysieren deine Daten nicht, und deine IP-Abfragen sind keiner Sitzung zugeordnet. Jede Anfrage geht vom Browser an öffentliche DNS- und IP-Geo-Dienste; die Antwort wird lokal gerendert.',
      front_trust_title: 'Keine Konten. Kein Tracking. Kein Quatsch.',
      front_trust_text: 'SiteTrace ist ein kleines, unabhängiges Tool für Leute, die schnelle Antworten wollen, ohne ihre Daten herzugeben. Nichts zu installieren, nichts zu registrieren, und es wird nichts über dich an Werbetreibende verkauft.',

      page_ip_title: 'Was ist meine IP? — SiteTrace',
      page_ip_desc: 'Finde deine öffentliche IP-Adresse, geografische Position, ISP und den Datenschutz-Status deiner Verbindung (VPN, Proxy, Tor) sofort. Keine Anmeldung erforderlich.',
      page_ping_title: 'Ping & Latenztest — SiteTrace',
