      page_status_title: 'Service-Status — SiteTrace',
      page_status_desc: 'Prüfe, ob deine Lieblingsdienste online oder gestört sind. Echtzeit-Status direkt von den offiziellen Statusseiten.',
      page_about_title: 'Über uns — SiteTrace',
      page_about_desc: 'SiteTrace ist ein kostenloses, anmeldefreies, datenschutzfreundliches Netzwerk-Tool. Hier erfährst du, wer es gebaut hat und warum.',
      page_privacy_title: 'Datenschutzerklärung — SiteTrace',
