      aff_title: 'Mehr Privatsphäre',
      aff_subtitle: 'Vertrauenswürdige, unabhängig geprüfte Tools, die unser Team tatsächlich nutzt.',
      aff_cta: 'Mehr erfahren',
      aff_1_name: 'NordVPN',
