      isitdown_all_systems_ok: 'Alle Systeme funktionsfähig',
      isitdown_eyebrow: 'Ist es down?',
      isitdown_title: 'Ist es für mich down?',
      isitdown_subtitle: 'Füge eine URL ein, um sofort zu prüfen, ob sie für dich erreichbar ist, oder sieh dir den Live-Status von über 50 beliebten Diensten an.',
