      isitdown_checking: 'Wird geprüft…',
      isitdown_your_network: 'Dein Netzwerk',
      isitdown_status_official: 'Offizieller Status',
      isitdown_tips_title: 'Was tun, wenn es down aussieht',
      isitdown_tip_reload: 'Lade die Seite neu (Strg/Cmd-R).',
      isitdown_tip_other: 'Versuche, die Website in einem anderen Browser oder Gerät im selben Netzwerk zu öffnen.',
      isitdown_tip_vpn: 'Wenn du ein VPN nutzt, trenne die Verbindung und versuche es erneut — manche Dienste blockieren VPN-Bereiche.',
      isitdown_tip_dns: 'Probiere einen anderen DNS (z. B. 1.1.1.1 oder 8.8.8.8) — dein ISP könnte die Domain entführen oder blockieren.',
      isitdown_tip_isp: 'Wenn nur manche Seiten nicht laden, blockt sie möglicherweise dein ISP oder Land. Ein seriöses VPN kann das bestätigen.',
      isitdown_pill_up: 'Sieht online aus',
      isitdown_pill_down: 'Wahrscheinlich down für dich',
