      about_h1: 'Over SiteTrace',
      about_p1: 'SiteTrace is een kleine set netwerktools voor wie snelle, eerlijke antwoorden wil over hoe het internet hen ziet. Geen registratie, geen app om te installeren, geen tracking die aan je identiteit is gekoppeld.',
      about_p2: 'Gebouwd door een klein team dat de "bekijk je IP"-sites met popups, autoplay-video\'s en "VPN-aanbevelingen" die alleen voor affiliate-commissies bestonden, zat was. SiteTrace doet het tegenovergestelde: het laadt direct, toont meteen het antwoord en zet elke tool op een eigen pagina, zodat je kunt linken, delen of gewoon de tool die je nodig hebt kunt bookmarken.',
      about_p3: 'Alle zoekopdrachten draaien in je browser en gaan naar publieke diensten (ipwho.is, ip-api.com, Google DNS-over-HTTPS, Cloudflare DNS-over-HTTPS, plus CORS-vriendelijke endpoints voor ping). We draaien geen server ertussen en loggen je verzoeken niet.',
      privacy_h1: 'Privacybeleid',
      privacy_short_h2: 'Kort samengevat',
      privacy_short: 'We loggen je IP-zoekopdrachten niet. We plaatsen geen tracking-cookies. We verkopen je data niet. We gebruiken geen analytics van derden op deze site. De enige data die je hier ziet, is die van jezelf.',
      privacy_data_h2: 'Welke data wordt verzameld',
      privacy_data: 'Wanneer je een tool op SiteTrace opent, doet je browser een verzoek aan een publieke IP-geo- of DNS-over-HTTPS-dienst. Die diensten hebben hun eigen privacybeleid. SiteTrace zit niet tussen jou en hen, logt die verzoeken niet en bewaart de antwoorden niet. Cloudflare (onze host) houdt standaard HTTP-logs bij voor beveiliging en misbruikpreventie, onder het privacybeleid van Cloudflare.',
      privacy_cookies_h2: 'Cookies en opslag',
      privacy_cookies: 'SiteTrace gebruikt geen cookies. Het gebruikt geen localStorage, sessionStorage, IndexedDB of andere persistente opslag. De taalvoorkeur wordt alleen in het geheugen bewaard en reset wanneer je het tabblad sluit.',
      privacy_third_h2: 'Diensten van derden',
      privacy_third: 'Om je verzoeken te beantwoorden, praat je browser met: ipwho.is, ip-api.com, Google DNS-over-HTTPS en Cloudflare DNS-over-HTTPS. Zij zien je IP, maar SiteTrace niet. Elk heeft een eigen privacybeleid.',
      privacy_contact_h2: 'Contact',
      privacy_contact: 'Vragen? Mail appenzeller.digitalstore@gmail.com.',
      back_to_home: 'Terug naar SiteTrace',

      footer_disclaimer: 'SiteTrace is een gratis diagnosetool. Er wordt geen data opgeslagen op onze servers. De resultaten tonen wat het openbare internet op dit moment over je verbinding kan zien.',
      footer_about: 'Over',
      footer_privacy: 'Privacy',
      footer_contact: 'Contact',
      footer_rights: 'Alle rechten voorbehouden.',

