      dns_how_title: 'Hoe werken DNS-lookups?',
      dns_how_text: 'DNS (Domain Name System) is het adresboek van het internet. Wanneer je example.com in een browser typt, vertaalt DNS die mens-leesbare naam naar het IP-adres dat de computer nodig heeft. Deze pagina bevragen alle veelvoorkomende recordtypes — A, AAAA, MX, TXT, NS, CNAME, SOA — parallel en groepeert de antwoorden. Queries gaan via DNS-over-HTTPS (Google + Cloudflare), zodat je lookups privé zijn.',
      dns_how_record_types: 'Recordtypes',
