      isitdown_tip_dns: 'Probeer een andere DNS (bijv. 1.1.1.1 of 8.8.8.8) — je provider kap mogelijk het domein of blokkeert het.',
      isitdown_tip_isp: 'Als alleen sommige sites falen, blokkeert je provider of land ze mogelijk. Een betrouwbare VPN kan dit bevestigen.',
