      about_h1: 'O SiteTrace',
      about_p1: 'SiteTrace to mały zestaw narzędzi sieciowych dla osób, które chcą szybkich, uczciwych odpowiedzi o tym, jak widzi je internet. Bez rejestracji, bez aplikacji do instalacji, bez śledzenia powiązanego z twoją tożsamością.',
      about_p2: 'Zbudowany przez mały zespół, który miał dość stron „sprawdź swoje IP" zasypanych popupami, filmami odtwarzanymi automatycznie i „rekomendacjami VPN", które istniały tylko po to, by zgarniać prowizje afiliacyjne. SiteTrace robi odwrotnie: ładuje się natychmiast, pokazuje odpowiedź od razu i umieszcza każde narzędzie na osobnej stronie, żebyś mógł je udostępnić, wysłać komuś lub po prostu dodać do zakładek.',
      about_p3: 'Wszystkie zapytania działają w twojej przeglądarce i idą do publicznych serwisów (ipwho.is, ip-api.com, Google DNS-over-HTTPS, Cloudflare DNS-over-HTTPS, plus endpointy zgodne z CORS do pingów). Nie stoi między tobą a nimi żaden nasz serwer i nie logujemy twoich zapytań.',
      privacy_h1: 'Polityka prywatności',
      privacy_short_h2: 'W skrócie',
      privacy_short: 'Nie logujemy twoich wyszukiwań IP. Nie ustawiamy ciasteczek śledzących. Nie sprzedajemy twoich danych. Nie używamy analityki firm trzecich na tej stronie. Jedyne dane, które tu widzisz, to twoje własne.',
      privacy_data_h2: 'Jakie dane zbieramy',
      privacy_data: 'Gdy otwierasz dowolne narzędzie SiteTrace, twoja przeglądarka wysyła zapytanie do publicznego serwisu IP-geo lub DNS-over-HTTPS. Te serwisy mają własne polityki prywatności. SiteTrace nie stoi między tobą a nimi, nie loguje tych zapytań i nie przechowuje odpowiedzi. Cloudflare (nasz hosting) trzyma standardowe logi HTTP do celów bezpieczeństwa i zapobiegania nadużyciom, zgodnie z polityką prywatności Cloudflare.',
      privacy_cookies_h2: 'Ciasteczka i pamięć',
      privacy_cookies: 'SiteTrace nie używa ciasteczek. Nie używa localStorage, sessionStorage, IndexedDB ani żadnej innej trwałej pamięci. Preferencja języka jest trzymana tylko w pamięci i resetuje się po zamknięciu karty.',
      privacy_third_h2: 'Usługi firm trzecich',
      privacy_third: 'Aby odpowiedzieć na twoje zapytania, twoja przeglądarka komunikuje się z: ipwho.is, ip-api.com, Google DNS-over-HTTPS i Cloudflare DNS-over-HTTPS. Widzą twoje IP, ale SiteTrace nie. Każdy z nich ma własną politykę prywatności.',
