      dns_how_text: 'DNS (Domain Name System) to książka adresowa internetu. Gdy wpisujesz example.com w przeglądarce, DNS tłumaczy tę czytelną dla ludzi nazwę na adres IP, którego potrzebuje komputer. Ta strona odpytuje wszystkie popularne typy rekordów — A, AAAA, MX, TXT, NS, CNAME, SOA — równolegle i grupuje odpowiedzi. Zapytania przesyłane są przez DNS-over-HTTPS (Google + Cloudflare), dzięki czemu twoje wyszukiwania są prywatne.',
