      dns_how_record_a: 'A — mapuje nazwę na adres IPv4.',
      dns_how_record_aaaa: 'AAAA — mapuje nazwę na adres IPv6.',
      dns_how_record_mx: 'MX — listuje serwery pocztowe przyjmujące e-mail dla domeny.',
      dns_how_record_txt: 'TXT — dowolny tekst, często używany do weryfikacji domeny (Google, Microsoft) i polityki e-mail (SPF, DKIM, DMARC).',
      dns_how_record_ns: 'NS — listuje autorytatywne serwery nazw dla domeny.',
      dns_how_record_cname: 'CNAME — tworzy alias z jednej nazwy na drugą.',
      dns_how_record_soa: 'SOA — informacje administracyjne o strefie (serial, refresh, retry, expire, minimalny TTL).',
