      front_feature_dns_desc: 'DNS-over-HTTPS로 모든 도메인을 A, AAAA, MX, TXT, NS, CNAME, SOA 레코드로 확인. 어떤 리졸버가 응답했는지 표시.',
      front_feature_status_title: '서비스 상태',
      front_feature_status_desc: '모두에게 장애인가요, 나에게만인가요? Cloudflare, GitHub, Discord, OpenAI, Vercel 등 11개 이상의 실시간 상태를 각 공식 상태 페이지에서 직접 가져옵니다.',
      front_cta: '열기',
      front_how_title: '작동 방식',
      front_how_text: '모든 검사는 브라우저에서 직접 실행됩니다 — 로그를 보관하지 않고, 데이터를 분석하지 않으며, IP 조회는 세션에 연결되지 않습니다. 각 요청은 브라우저에서 공개 DNS와 IP 지오 서비스로 보내지고, 응답은 로컬에서 렌더링됩니다.',
      front_trust_title: '계정 없음. 추적 없음. 군더더기 없음.',
      front_trust_text: 'SiteTrace는 데이터를 내주지 않으면서 빠른 답을 원하는 사용자를 위한 작고 독립적인 도구입니다. 설치도, 가입도, 광고주를 위한 당신 정보 판매도 없습니다.',

      page_ip_title: '내 IP 주소는? — SiteTrace',
      page_ip_desc: '공개 IP 주소, 지리적 위치, ISP, 그리고 연결의 개인정보 보호 상태(VPN, 프록시, Tor)를 즉시 확인. 로그인 불필요.',
      page_ping_title: 'Ping 및 지연 테스트 — SiteTrace',
      page_ping_desc: '9개의 주요 글로벌 서버에 대한 연결 지연을 측정. 라이브, 가벼움, 설치 없음.',
      page_dns_title: 'DNS 조회 — SiteTrace',
