      page_status_title: '서비스 상태 — SiteTrace',
      page_status_desc: '좋아하는 서비스가 온라인인지 오프라인인지 공식 상태 페이지에서 실시간으로 확인하세요.',
      page_about_title: '소개 — SiteTrace',
