      about_h1: 'SiteTrace 소개',
      about_p1: 'SiteTrace는 인터넷이 자신을 어떻게 보는지에 대한 빠르고 정직한 답을 원하는 사람들을 위한 작은 네트워크 도구 모음입니다. 가입도, 설치할 앱도, 신원과 연결된 추적도 없습니다.',
      about_p2: '팝업과 자동 재생 동영상, 어필리에이트 수수료만 챙기기 위한 "VPN 추천"으로 가득한 "내 IP 보기" 사이트에 지친 작은 팀이 만들었습니다. SiteTrace는 그 반대입니다. 즉시 로드되고, 답을 바로 보여주며, 각 도구를 자체 페이지에 배치해 링크·공유·북마크가 자유롭습니다.',
      about_p3: '모든 조회는 브라우저에서 실행되어 공개 서비스(ipwho.is, ip-api.com, Google DNS-over-HTTPS, Cloudflare DNS-over-HTTPS, Ping용 CORS 지원 엔드포인트)로 향합니다. 중간에 우리 서버는 없으며, 요청을 로그에 남기지 않습니다.',
      privacy_h1: '개인정보 처리방침',
      privacy_short_h2: '요약',
      privacy_short: 'IP 조회를 로그에 남기지 않습니다. 추적 쿠키를 설정하지 않습니다. 데이터를 판매하지 않습니다. 이 사이트에 제3자 분석을 사용하지 않습니다. 여기서 보게 되는 유일한 데이터는 사용자의 데이터입니다.',
      privacy_data_h2: '수집되는 데이터',
      privacy_data: 'SiteTrace에서 도구를 열면 브라우저는 공개 IP 지오 또는 DNS-over-HTTPS 서비스에 요청을 보냅니다. 해당 서비스는 각자의 개인정보 처리방침을 가지고 있습니다. SiteTrace는 사용자와 그 서비스 사이에 있지 않으며, 요청을 로그에 남기지 않고 응답을 저장하지도 않습니다. Cloudflare(호스트)는 보안 및 남용 방지를 위해 표준 HTTP 요청 로그를 보관하며, 이는 Cloudflare 개인정보 처리방침을 따릅니다.',
      privacy_cookies_h2: '쿠키 및 저장',
      privacy_cookies: 'SiteTrace는 쿠키를 사용하지 않습니다. localStorage, sessionStorage, IndexedDB 또는 기타 영구 저장소도 사용하지 않습니다. 언어 설정은 메모리에만 보관되며 탭을 닫으면 초기화됩니다.',
      privacy_third_h2: '제3자 서비스',
      privacy_third: '사용자 요청에 응답하기 위해 브라우저는 다음 서비스와 통신합니다: ipwho.is, ip-api.com, Google DNS-over-HTTPS, Cloudflare DNS-over-HTTPS. 이들은 사용자의 IP를 보지만 SiteTrace는 보지 않습니다. 각 서비스는 자체 개인정보 처리방침을 가지고 있습니다.',
      privacy_contact_h2: '문의',
      privacy_contact: '질문은 appenzeller.digitalstore@gmail.com 으로 보내주세요.',
      back_to_home: 'SiteTrace로 돌아가기',

      footer_disclaimer: 'SiteTrace는 무료 진단 유틸리티입니다. 당사 서버에는 데이터가 저장되지 않습니다. 결과는 공개 인터넷이 이 순간 사용자의 연결에 대해 볼 수 있는 것을 반영합니다.',
