      about_h1: 'О SiteTrace',
      about_p1: 'SiteTrace — небольшой набор сетевых инструментов для тех, кто хочет быстрых и честных ответов о том, как интернет их видит. Без регистрации, без приложения, без слежки, привязанной к вашей личности.',
      about_p2: 'Создан небольшой командой, которой надоели сайты «узнай свой IP» с попапами, автопроигрываемым видео и «рекомендациями VPN», существующими только ради партнёрских комиссий. SiteTrace делает наоборот: загружается мгновенно, сразу показывает ответ и размещает каждый инструмент на отдельной странице, чтобы вы могли дать ссылку, поделиться или просто добавить в закладки нужный.',
      about_p3: 'Все запросы выполняются в вашем браузере и идут к публичным сервисам (ipwho.is, ip-api.com, Google DNS-over-HTTPS, Cloudflare DNS-over-HTTPS, а также CORS-совместимые эндпоинты для ping). У нас нет своего сервера посередине, и мы не логируем ваши запросы.',
      privacy_h1: 'Политика конфиденциальности',
      privacy_short_h2: 'Коротко',
      privacy_short: 'Мы не логируем ваши IP-запросы. Не ставим следящие cookie. Не продаём ваши данные. Не используем стороннюю аналитику на этом сайте. Единственные данные, которые вы здесь видите, — ваши собственные.',
      privacy_data_h2: 'Какие данные собираются',
      privacy_data: 'Когда вы открываете любой инструмент SiteTrace, ваш браузер делает запрос к публичному IP-гео или DNS-over-HTTPS сервису. У этих сервисов свои политики конфиденциальности. SiteTrace не стоит между вами и ними, не логирует эти запросы и не хранит ответы. Cloudflare (наш хостинг) хранит стандартные HTTP-логи для безопасности и предотвращения злоупотреблений в соответствии с политикой конфиденциальности Cloudflare.',
      privacy_cookies_h2: 'Cookie и хранение',
      privacy_cookies: 'SiteTrace не использует cookie. Не использует localStorage, sessionStorage, IndexedDB или любое другое постоянное хранилище. Языковое предпочтение хранится только в памяти и сбрасывается при закрытии вкладки.',
      privacy_third_h2: 'Сторонние сервисы',
      privacy_third: 'Чтобы отвечать на ваши запросы, ваш браузер общается с: ipwho.is, ip-api.com, Google DNS-over-HTTPS и Cloudflare DNS-over-HTTPS. Они видят ваш IP, а SiteTrace — нет. У каждого своя политика конфиденциальности.',
      privacy_contact_h2: 'Контакты',
      privacy_contact: 'Вопросы? Пишите на appenzeller.digitalstore@gmail.com.',
      back_to_home: 'Назад на SiteTrace',

      footer_disclaimer: 'SiteTrace — бесплатная диагностическая утилита. На наших серверах данные не хранятся. Результаты отражают то, что публичный интернет может видеть о вашем соединении в данный момент.',
      footer_about: 'О проекте',
      footer_privacy: 'Приватность',
      footer_contact: 'Контакты',
