      ping_cors_blocked: 'Ответ заблокирован CORS',
      ping_status_reachable_cors: 'Доступно (ответ не читается)',
      dns_how_title: 'Как работают DNS-запросы',
      dns_how_text: 'DNS (Domain Name System) — это адресная книга интернета. Когда вы вводите example.com в браузер, DNS переводит это читаемое человеком имя в IP-адрес, который нужен компьютеру для подключения. Эта страница запрашивает все распространённые типы записей (A, AAAA, MX, TXT, NS, CNAME, SOA) параллельно и группирует ответы. Запросы отправляются через DNS-over-HTTPS (Google + Cloudflare), чтобы ваши запросы оставались приватными.',
      dns_how_record_types: 'Типы записей',
