      isitdown_tip_vpn: 'Если вы используете VPN, отключитесь и попробуйте снова — некоторые сервисы блокируют VPN-диапазоны.',
      isitdown_tip_dns: 'Попробуйте другой DNS (напр. 1.1.1.1 или 8.8.8.8) — ваш провайдер может перехватывать или блокировать домен.',
      isitdown_tip_isp: 'Если не загружаются только некоторые сайты, возможно, ваш провайдер или страна их блокирует. Надёжный VPN может это подтвердить.',
