      about_h1: 'SiteTrace hakkında',
      about_p1: 'SiteTrace, internetin kendilerini nasıl gördüğüne dair hızlı ve dürüst cevaplar isteyen kişiler için küçük bir ağ aracı setidir. Kayıt yok, kurulacak uygulama yok, kimliğinize bağlı takip yok.',
      about_p2: 'Pop-up\'larla, otomatik oynatılan videolarla ve sadece ortaklık komisyonu için var olan "VPN önerileri"yle dolu "IP\'nizi görün" sitelerinden bıkmış küçük bir ekip tarafından yapıldı. SiteTrace tam tersini yapar: anında yüklenir, cevabı hemen gösterir ve her aracı kendi sayfasına koyar; böylece paylaşabilir, gönderebilir ya da sadece ihtiyacınız olanı yer imlerine ekleyebilirsiniz.',
