      privacy_short: 'IP sorgularınızı loglamayız. Takip çerezi koymayız. Verilerinizi satmayız. Bu sitede üçüncü taraf analitiği kullanmayız. Burada gördüğünüz tek veri kendi verinizdir.',
      privacy_data_h2: 'Hangi veriler toplanır',
      privacy_data: 'SiteTrace\'te bir araç açtığınızda, tarayıcınız genel bir IP-coğrafi veya DNS-over-HTTPS servisine istek gönderir. Bu servislerin kendi gizlilik politikaları vardır. SiteTrace sizinle onların arasında değildir, bu istekleri loglamaz ve yanıtları saklamaz. Cloudflare (hosting sağlayıcımız) güvenlik ve kötüye kullanımı önlemek için standart HTTP istek loglarını tutar; bu Cloudflare Gizlilik Politikası\'na tabidir.',
      privacy_cookies_h2: 'Çerezler ve depolama',
      privacy_cookies: 'SiteTrace çerez kullanmaz. localStorage, sessionStorage, IndexedDB veya başka bir kalıcı depolama kullanmaz. Dil tercihi yalnızca bellekte tutulur ve sekmeyi kapattığınızda sıfırlanır.',
      privacy_third_h2: 'Üçüncü taraf servisler',
      privacy_third: 'Sorgularınızı yanıtlamak için tarayıcınız şu servislerle iletişim kurar: ipwho.is, ip-api.com, Google DNS-over-HTTPS ve Cloudflare DNS-over-HTTPS. Onlar IP\'nizi görür ama SiteTrace görmez. Her birinin kendi gizlilik politikası vardır.',
      privacy_contact_h2: 'İletişim',
      privacy_contact: 'Sorular? appenzeller.digitalstore@gmail.com adresine e-posta gönderin.',
      back_to_home: 'SiteTrace\'e dön',

      footer_disclaimer: 'SiteTrace ücretsiz bir tanılama aracıdır. Sunucularımızda hiçbir veri saklanmaz. Sonuçlar, genel internetin bağlantınız hakkında şu anda görebildiğini yansıtır.',
      footer_about: 'Hakkında',
