      dns_how_title: 'DNS sorguları nasıl çalışır',
      dns_how_text: 'DNS (Alan Adı Sistemi), internetin adres defteridir. Bir tarayıcıya example.com yazdığınızda, DNS bu insan tarafından okunabilir adı bilgisayarın gerçekten ihtiyaç duyduğu IP adresine çevirir. Bu sayfa, tüm yaygın kayıt türlerini (A, AAAA, MX, TXT, NS, CNAME, SOA) paralel olarak sorgular ve yanıtları gruplandırır. Sorgular DNS-over-HTTPS (Google + Cloudflare) üzerinden gönderilir, böylece aramalarınız gizli kalır.',
