      isitdown_tip_other: 'Siteyi aynı ağdaki başka bir tarayıcıda veya cihazda açmayı deneyin.',
      isitdown_tip_vpn: 'VPN kullanıyorsanız, bağlantıyı kesin ve tekrar deneyin — bazı hizmetler VPN aralıklarını engeller.',
      isitdown_tip_dns: 'Başka bir DNS deneyin (ör. 1.1.1.1 veya 8.8.8.8) — ISS\'niz alan adını ele geçiriyor veya engelliyor olabilir.',
      isitdown_tip_isp: 'Yalnızca bazı siteler başarısız oluyorsa, ISS\'niz veya ülkeniz bunları engelliyor olabilir. Saygın bir VPN bunu doğrulayabilir.',
      isitdown_pill_up: 'Çevrimiçi görünüyor',
