      about_p1: 'SiteTrace 是一组小巧的网络工具，为那些想要快速、诚实地了解互联网如何看待自己的人打造。无需注册，无需安装任何应用，也没有与你身份绑定的追踪。',
      about_p2: '它由一个小型团队打造，他们受够了那些塞满弹窗、自动播放视频和"VPN 推荐"（只为赚取佣金）的"查看我的 IP"网站。SiteTrace 走了相反的路：它瞬间加载，立刻给出答案，并把每个工具放在各自的页面上，方便你链接、分享或直接收藏需要的那个。',
