      privacy_short: '我们不记录你的 IP 查询。不设置追踪 cookie。不卖你的数据。本站不使用第三方分析。你在这里看到的唯一数据是你自己的。',
      privacy_data_h2: '收集哪些数据',
      privacy_data: '当你打开 SiteTrace 的任何工具时，你的浏览器会向一个公共的 IP 地理或 DNS-over-HTTPS 服务发起请求。这些服务有它们自己的隐私政策。SiteTrace 不在它们和你之间，不记录这些请求，也不存储响应。Cloudflare（我们的托管方）会保留标准的 HTTP 请求日志用于安全和防滥用，遵循 Cloudflare 的隐私政策。',
