      dns_how_title: 'DNS 查询的工作原理',
      dns_how_text: 'DNS(域名系统)是互联网的地址簿。当你在浏览器中输入 example.com 时,DNS 会将这个人类可读的名称转换为计算机实际需要的 IP 地址。此页面并行查询所有常见记录类型(A、AAAA、MX、TXT、NS、CNAME、SOA)并对答案进行分组。查询通过 DNS-over-HTTPS(Google + Cloudflare)发送,以确保你的查询是私密的。',
