      about_h1: 'Tentang SiteTrace',
      about_p1: 'SiteTrace adalah seperangkat alat jaringan kecil untuk orang yang ingin jawaban cepat dan jujur tentang bagaimana internet melihat mereka. Tanpa pendaftaran, tanpa aplikasi untuk diinstal, dan tanpa pelacakan yang terikat pada identitas Anda.',
      about_p2: 'Dibuat oleh tim kecil yang muak dengan situs "lihat IP Anda" yang penuh popup, video autoplay, dan "rekomendasi VPN" yang ada hanya untuk komisi afiliasi. SiteTrace melakukan kebalikannya: ia dimuat seketika, langsung menunjukkan jawabannya, dan menaruh setiap alat di halamannya sendiri supaya Anda bisa menautkannya, membagikannya, atau cukup mem-bookmark yang Anda butuhkan.',
      about_p3: 'Semua pencarian berjalan di peramban Anda dan menuju layanan publik (ipwho.is, ip-api.com, Google DNS-over-HTTPS, Cloudflare DNS-over-HTTPS, plus endpoint yang CORS-friendly untuk ping). Kami tidak menjalankan server di tengah dan tidak mencatat permintaan Anda.',
      privacy_h1: 'Kebijakan Privasi',
      privacy_short_h2: 'Singkatnya',
      privacy_short: 'Kami tidak mencatat pencarian IP Anda. Tidak memasang cookie pelacakan. Tidak menjual data Anda. Tidak menggunakan analitik pihak ketiga di situs ini. Satu-satunya data yang Anda lihat di sini adalah data Anda sendiri.',
      privacy_data_h2: 'Data apa yang dikumpulkan',
      privacy_data: 'Saat Anda membuka alat SiteTrace apa pun, peramban Anda membuat permintaan ke layanan IP-geo atau DNS-over-HTTPS publik. Layanan-layanan tersebut memiliki kebijakan privasi masing-masing. SiteTrace tidak berada di antara Anda dan mereka, tidak mencatat permintaan tersebut, dan tidak menyimpan responsnya. Cloudflare (host kami) menyimpan log permintaan HTTP standar untuk keamanan dan pencegahan penyalahgunaan, sesuai Kebijakan Privasi Cloudflare.',
      privacy_cookies_h2: 'Cookie dan penyimpanan',
      privacy_cookies: 'SiteTrace tidak menggunakan cookie. Tidak menggunakan localStorage, sessionStorage, IndexedDB, atau penyimpanan persisten lainnya. Preferensi bahasa disimpan hanya di memori dan direset saat Anda menutup tab.',
      privacy_third_h2: 'Layanan pihak ketiga',
      privacy_third: 'Untuk menjawab permintaan Anda, peramban Anda berkomunikasi dengan: ipwho.is, ip-api.com, Google DNS-over-HTTPS, dan Cloudflare DNS-over-HTTPS. Mereka melihat IP Anda, tapi SiteTrace tidak. Tiap layanan punya kebijakan privasi sendiri.',
