      ip_h1: 'Apa alamat IP saya?',
      ip_intro_h2: 'Tentang pemeriksa IP ini',
      ip_intro_text: 'Alamat IP publik Anda adalah nomor unik yang mengidentifikasi perangkat Anda di internet publik. Setiap situs yang Anda kunjungi, setiap API yang Anda panggil, dan setiap surel yang Anda kirim menggunakannya. SiteTrace menunjukkan informasi yang sama yang dapat dilihat oleh layanan mana pun saat Anda terhubung — IP Anda, lokasi geografis perkiraan, penyedia layanan internet, dan apakah lalu lintas Anda dirutekan melalui VPN, proxy, atau Tor.',
