      front_feature_status_title: 'Trạng thái dịch vụ',
      front_feature_status_desc: 'Nó sập cho tất cả mọi người hay chỉ bạn? Kiểm tra trạng thái trực tiếp của Cloudflare, GitHub, Discord, OpenAI, Vercel và 11+ dịch vụ khác. Dữ liệu lấy thẳng từ trang trạng thái chính thức.',
      front_cta: 'Mở',
      front_how_title: 'Cách hoạt động',
