      page_ping_title: 'Ping & đo độ trễ — SiteTrace',
      page_ping_desc: 'Đo độ trễ kết nối của bạn tới 9 máy chủ toàn cầu lớn. Trực tiếp, nhẹ, không cần cài đặt.',
      page_dns_title: 'Tra cứu DNS — SiteTrace',
