      page_about_title: 'Giới thiệu — SiteTrace',
      page_about_desc: 'SiteTrace là công cụ mạng miễn phí, không cần đăng nhập, tôn trọng quyền riêng tư. Đây là ai đã tạo nó và vì sao.',
      page_privacy_title: 'Chính sách bảo mật — SiteTrace',
