      about_h1: 'Về SiteTrace',
      about_p1: 'SiteTrace là một bộ công cụ mạng nhỏ dành cho những ai muốn câu trả lời nhanh và trung thực về cách internet nhìn nhận họ. Không đăng ký, không cần cài ứng dụng, và không có theo dõi gắn với danh tính của bạn.',
      about_p2: 'Được tạo bởi một nhóm nhỏ đã chán ngán những trang "xem IP của bạn" đầy popup, video tự phát và "gợi ý VPN" chỉ tồn tại để ăn hoa hồng. SiteTrace làm ngược lại: tải tức thì, hiện ngay câu trả lời, và đặt mỗi công cụ trên một trang riêng để bạn có thể chia sẻ, gửi cho ai đó, hoặc chỉ đánh dấu trang cái bạn cần.',
      about_p3: 'Mọi tra cứu chạy trong trình duyệt của bạn và đi tới các dịch vụ công cộng (ipwho.is, ip-api.com, Google DNS-over-HTTPS, Cloudflare DNS-over-HTTPS, cùng các endpoint hỗ trợ CORS cho ping). Chúng tôi không chạy máy chủ ở giữa và không ghi log yêu cầu của bạn.',
      privacy_h1: 'Chính sách bảo mật',
      privacy_short_h2: 'Tóm tắt',
      privacy_short: 'Chúng tôi không ghi log các tra cứu IP của bạn. Không đặt cookie theo dõi. Không bán dữ liệu của bạn. Không dùng phân tích bên thứ ba trên trang này. Dữ liệu duy nhất bạn thấy ở đây là của chính bạn.',
      privacy_data_h2: 'Dữ liệu nào được thu thập',
      privacy_data: 'Khi bạn mở bất kỳ công cụ nào của SiteTrace, trình duyệt của bạn gửi một yêu cầu tới dịch vụ IP-geo hoặc DNS-over-HTTPS công cộng. Những dịch vụ đó có chính sách bảo mật riêng. SiteTrace không đứng giữa bạn và họ, không ghi log các yêu cầu đó, và không lưu phản hồi. Cloudflare (nhà cung cấp hosting) giữ log yêu cầu HTTP tiêu chuẩn cho mục đích bảo mật và chống lạm dụng, theo Chính sách bảo mật của Cloudflare.',
      privacy_cookies_h2: 'Cookie và bộ nhớ',
      privacy_cookies: 'SiteTrace không dùng cookie. Không dùng localStorage, sessionStorage, IndexedDB hay bất kỳ bộ nhớ bền vững nào khác. Tùy chọn ngôn ngữ chỉ được giữ trong bộ nhớ và được đặt lại khi bạn đóng tab.',
      privacy_third_h2: 'Dịch vụ bên thứ ba',
      privacy_third: 'Để trả lời các yêu cầu của bạn, trình duyệt giao tiếp với: ipwho.is, ip-api.com, Google DNS-over-HTTPS và Cloudflare DNS-over-HTTPS. Họ thấy IP của bạn, nhưng SiteTrace không. Mỗi dịch vụ có chính sách bảo mật riêng.',
      privacy_contact_h2: 'Liên hệ',
      privacy_contact: 'Có câu hỏi? Gửi email tới appenzeller.digitalstore@gmail.com.',
      back_to_home: 'Về SiteTrace',

      footer_disclaimer: 'SiteTrace là công cụ chẩn đoán miễn phí. Không có dữ liệu nào được lưu trên máy chủ của chúng tôi. Kết quả phản ánh những gì internet công cộng có thể thấy về kết nối của bạn ở thời điểm này.',
      footer_about: 'Giới thiệu',
