      about_h1: 'Om SiteTrace',
      about_p1: 'SiteTrace är en liten samling nätverksverktyg för dig som vill ha snabba, ärliga svar på hur internet ser dig. Ingen registrering, ingen app att installera, och ingen spårning knuten till din identitet.',
      about_p2: 'Byggt av ett litet team som var trötta på "se din IP"-sajter fulla med popup-fönster, autoplay-video och "VPN-rekommendationer" som bara fanns för att casha affiliate-provisioner. SiteTrace gör tvärtom: det laddar direkt, visar svaret på en gång och lägger varje verktyg på en egen sida så att du kan länka till det, dela det eller bara bokmärka det du behöver.',
      about_p3: 'Alla sökningar körs i din webbläsare och går till publika tjänster (ipwho.is, ip-api.com, Google DNS-over-HTTPS, Cloudflare DNS-over-HTTPS, samt CORS-vänliga endpoints för ping). Vi kör ingen server i mitten och vi loggar inte dina förfrågningar.',
      privacy_h1: 'Integritetspolicy',
      privacy_short_h2: 'Kort version',
      privacy_short: 'Vi loggar inte dina IP-sökningar. Vi sätter inte spårningscookies. Vi säljer inte dina data. Vi använder ingen tredjepartsanalys på den här sidan. Den enda data du ser här är din egen.',
      privacy_data_h2: 'Vilken data samlas in',
      privacy_data: 'När du öppnar ett verktyg på SiteTrace gör din webbläsare en förfrågan till en publik IP-geo- eller DNS-over-HTTPS-tjänst. De tjänsterna har sina egna integritetspolicyer. SiteTrace sitter inte mellan dig och dem, loggar inte dessa förfrågningar och lagrar inte svaren. Cloudflare (vår värd) behåller standardmässiga HTTP-förfrågningsloggar för säkerhet och missbruksskydd, enligt Cloudflares integritetspolicy.',
      privacy_cookies_h2: 'Cookies och lagring',
      privacy_cookies: 'SiteTrace använder inga cookies. Det använder inte localStorage, sessionStorage, IndexedDB eller annan bestående lagring. Språkinställningen hålls bara i minnet och återställs när du stänger fliken.',
      privacy_third_h2: 'Tredjepartstjänster',
      privacy_third: 'För att svara på dina förfrågningar pratar din webbläsare med: ipwho.is, ip-api.com, Google DNS-over-HTTPS och Cloudflare DNS-over-HTTPS. De ser din IP, men SiteTrace gör det inte. Var och en har sin egen integritetspolicy.',
      privacy_contact_h2: 'Kontakt',
      privacy_contact: 'Frågor? Mejla appenzeller.digitalstore@gmail.com.',
      back_to_home: 'Tillbaka till SiteTrace',

      footer_disclaimer: 'SiteTrace är ett gratis diagnostikverktyg. Ingen data lagras på våra servrar. Resultaten speglar vad det öppna internet kan se om din anslutning just nu.',
